async function api(path,options){const response=await fetch(path,options);let data;try{data=await response.json()}catch{throw new Error('The server returned an unreadable response.')}if(response.status===401){$('#welcome').hidden=true;$('#shell').hidden=true;$('#login').hidden=false;throw new Error(data.error)}if(!response.ok)throw new Error(data.error||'Something went wrong.');return data}
function params(){const end=new Date(),start=new Date();start.setUTCDate(end.getUTCDate()-state.days+1);const q=new URLSearchParams({project:state.project.id,from:start.toISOString().slice(0,10),to:end.toISOString().slice(0,10)});if(state.segmentProperty&&state.segmentValue){q.set('property',state.segmentProperty);q.set('value',state.segmentValue)}return q}
function query(path){return path+'?'+params()}
function pageConfig(view){const pages=state.lang==='id'?{overview:['GAMBARAN UTAMA','Ringkasan produk','Lihat apa yang terjadi. Pahami apa yang berhasil.'],events:['SETIAP TINDAKAN BERCERITA','Penjelajah event','Ikuti aktivitas di balik setiap keputusan produk.'],funnels:['DARI LANGKAH AWAL KE NILAI','Funnel konversi','Temukan hambatan. Bantu lebih banyak pengguna mencapai tujuan.'],retention:['BERI ALASAN UNTUK KEMBALI','Retensi pengguna','Pahami apa yang membuat pengguna kembali.'],paths:['PERJALANAN NYATA','Alur pengguna','Temukan langkah yang benar-benar diambil pengguna.'],people:['DI BALIK SETIAP DATA','Pengguna Anda','Kenali pengguna di balik aktivitas.'],saved:['PERTANYAAN YANG TERSIMPAN','Analisis tersimpan','Kembali ke pertanyaan penting tanpa membangun ulang.'],workspace:['KERJA BERSAMA','Ruang kerja','Kelola akses, konteks, dan peringatan tim.'],guide:['MULAI DENGAN PERTANYAAN','Cara menggunakan Pulse','Dari event pertama hingga keputusan produk yang lebih baik.'],setup:['DATA BAIK DIMULAI DI SINI','Hubungkan produk Anda','Beberapa baris kode. Perspektif yang benar-benar baru.'],health:['PERCAYA PADA SINYAL','Kesehatan pelacakan','Temukan masalah instrumentasi sebelum memengaruhi keputusan.'],settings:['ATUR SESUAI KEBUTUHAN','Pengaturan proyek','Satu layanan mandiri untuk semua produk Anda.']}:{overview:['THE BIG PICTURE','Product overview','See what’s happening. Understand what’s working.'],events:['EVERY ACTION TELLS A STORY','Event explorer','Follow the activity behind every product decision.'],funnels:['FROM FIRST TOUCH TO AHA','Conversion funnels','Find the friction. Help more people find their way.'],retention:['GIVE THEM A REASON TO RETURN','User retention','Understand what brings your people back.'],paths:['THE JOURNEY AS IT HAPPENS','User paths','Discover the routes people actually take through your product.'],people:['BEHIND EVERY DATA POINT','Your people','Get to know the people behind the activity.'],saved:['QUESTIONS WORTH RETURNING TO','Saved analyses','Return to important questions without rebuilding them.'],workspace:['WORK BETTER TOGETHER','Workspace','Manage team access, shared context, and alerts.'],guide:['START WITH A QUESTION','How to use Pulse','From your first event to a better product decision.'],setup:['GOOD DATA STARTS HERE','Connect your product','A few lines of code. A whole new perspective.'],health:['TRUST THE SIGNAL','Tracking health','Catch instrumentation issues before they shape a decision.'],settings:['MAKE YOURSELF AT HOME','Project settings','One independent service. All your products.']};return pages[view]}
function showWelcome(authenticated){
 state.authenticated=authenticated;
 $('#welcome').hidden=false;$('#shell').hidden=true;$('#login').hidden=true;
 $('#welcome-start').innerHTML=authenticated?'Create your first project <span>→</span>':'Get started <span>→</span>';
 $('#welcome-auth-step').classList.toggle('complete',authenticated);
 $('#welcome-auth-step h3').textContent=authenticated?'Workspace connected':'Open your workspace';
 $('#welcome-auth-step p').textContent=authenticated?'You’re signed in. Let’s add your first product.':'Sign in with the admin token from your server.';
}
async function boot(){
 try{
  const response=await fetch('/api/projects');
  if(response.status===401){
   const installation=await fetch('/api/installation');
   if(!installation.ok)throw new Error('Unable to check installation status. Refresh to try again.');
   const status=await installation.json();
   if(status.setup_required){showWelcome(false)}else{$('#welcome').hidden=true;$('#shell').hidden=true;$('#login').hidden=false}
   return;
  }
  if(!response.ok)throw new Error('Unable to load your workspace. Refresh to try again.');
  state.projects=await response.json();state.authenticated=true;state.user=await api('/api/me');
  if(!state.projects.length){showWelcome(true);return}
  let saved;try{saved=localStorage.getItem('pulse-project')||localStorage.getItem('productAnalytics-project')}catch{}
  state.project=state.projects.find(p=>p.id===saved)||state.projects[0];
  $('#welcome').hidden=true;$('#login').hidden=true;$('#shell').hidden=false;renderProjects();await route();
 }catch(e){$('#welcome').hidden=true;$('#shell').hidden=true;$('#login').hidden=false;$('#login-error').textContent=e.message}
}
function renderProjects(){if(state.project){$('#project-name').textContent=state.project.name;$('#chip-name').textContent=state.project.name;$('.project-avatar').textContent=state.project.name[0].toUpperCase()}else{$('#project-name').textContent=state.lang==='id'?'Buat proyek':'Create a project';$('#chip-name').textContent=state.lang==='id'?'Belum ada proyek':'No project'}const canCreate=state.user?.role==='owner';$('#new-project').hidden=!canCreate;$('#project-menu').innerHTML=state.projects.map(p=>`<button data-project="${esc(p.id)}">${esc(p.name)} ${p.id===state.project?.id?'✓':''}</button>`).join('')+(canCreate?`<button data-add-project>＋ ${state.lang==='id'?'Tambah proyek':'Add a project'}</button>`:'')}
async function route(){
 const view=location.hash.slice(1)||'overview';state.view=pageConfig(view)?view:'overview';const c=pageConfig(state.view);
 $('#page-eyebrow').textContent=c[0];$('#page-title').innerHTML=esc(c[1])+'<span class="heading-dot">.</span>';$('#page-subtitle').textContent=c[2];$('#crumb').textContent=c[1];
 document.querySelectorAll('[data-view]').forEach(a=>a.classList.toggle('active',a.dataset.view===state.view));
 const quietViews=['guide','setup','health','settings','saved','workspace'];$('#toolbar').hidden=quietViews.includes(state.view);$('#save-view').hidden=quietViews.includes(state.view)||state.user?.role==='viewer';
 $('#segment-property').value=state.segmentProperty;$('#segment-value').value=state.segmentValue;$('#clear-segment').hidden=!(state.segmentProperty||state.segmentValue);
 const request=++state.request;if(!state.project&&state.view!=='guide'){$('#content').innerHTML=state.lang==='id'?empty('Keputusan baik Anda dimulai di sini.','Buat proyek pertama untuk memahami cara pengguna memakai produk Anda.','Buat proyek','new'):empty('Your next good decision starts here.','Create your first project to start understanding how people use your product.','Create a project','new');return}
 $('#content').innerHTML=`<div class="loading">${t('loading')}</div>`;
 try{const views={overview,events:eventsView,funnels,retention,paths,people,saved:savedAnalyses,workspace,guide,setup,health,settings};const html=await views[state.view]();if(request!==state.request)return;$('#content').innerHTML=html;bindView();$('#updated').removeAttribute('data-i18n');$('#updated').textContent=t('updated')+' '+new Date().toLocaleTimeString(state.lang==='id'?'id-ID':'en-US',{hour:'2-digit',minute:'2-digit'})}catch(e){if(request===state.request)$('#content').innerHTML=`<div class="error-box">${esc(e.message)} <button class="text-link" data-retry>${t('try_again')} →</button></div>`}
}
function empty(title,text,action='Set up tracking',target='setup'){return `<div class="panel empty"><div class="empty-icon">✧</div><h2>${esc(title)}</h2><p>${esc(text)}</p><button class="button primary" data-action="${esc(target)}">${esc(action)} →</button></div>`}
function percentage(value,previous){if(!previous)return value?t('new_value'):'—';const p=(value-previous)/previous*100;return `${p>=0?'↗':'↘'} ${Math.abs(p).toFixed(1)}%`}
function decisionBrief(d){const c=d.decision||{},m=d.metrics,p=d.previous||{},top=c.top_event?.name?c.top_event:d.top_events[0],share=c.top_event_share??(top?top.count/Math.max(m.events,1)*100:0),personShare=c.top_person_share||0,days=d.series.length,active=c.active_days||d.series.filter(point=>point.events).length;const readiness=c.readiness||'collecting';const labels={collecting:[t('collecting'),'orange'],directional:[t('directional'),'blue'],ready:[t('ready'),'green']};let headline,meaning,recommendation;if(state.lang==='id'){if(readiness==='collecting'){headline='Gunakan periode ini sebagai sinyal awal, bukan tren produk.';meaning=`Baru ${fmt(m.users)} pengguna yang diamati selama ${active} hari aktif dalam tampilan ${days} hari ini. Diperlukan cakupan yang lebih luas sebelum membandingkan performa produk.`;recommendation=share>=50&&top?`Periksa ${pretty(top.name)} dan pastikan pelacakan hanya aktif sekali untuk setiap tindakan yang dimaksud. Lalu kumpulkan aktivitas dari lebih banyak pengguna dan hari.`:'Terus kumpulkan aktivitas dari lebih banyak pengguna dan hari sebelum mengubah produk.'}else if(share>=50&&top){headline=`${pretty(top.name)} mendominasi aktivitas.`;meaning=`Event ini menyumbang ${share.toFixed(0)}% dari seluruh event. Pola yang terkonsentrasi dapat berarti keterlibatan nyata, perilaku berulang, atau event yang aktif terlalu sering.`;recommendation='Periksa event dan pengguna di baliknya sebelum menganggap volume tersebut sebagai keberhasilan produk.'}else if(p.events){const change=(m.events-p.events)/p.events*100;headline=`Aktivitas ${Math.abs(change).toFixed(0)}% ${change>=0?'lebih tinggi':'lebih rendah'} dibanding periode sebelumnya.`;meaning=`Sampel ini ${readiness==='ready'?'lebih luas dari batas minimum heuristik':'berguna sebagai sinyal awal'}, tetapi bukan bukti statistik. Event dan pengguna yang berkontribusi tetap perlu diperiksa.`;recommendation='Buka aliran event, temukan kontributor utama, dan pastikan perubahan tersebut mendukung sasaran produk Anda.'}else{headline='Sampel cukup luas untuk diteliti, tetapi belum memiliki data pembanding.';meaning='Gunakan konsentrasi event, funnel, dan retensi untuk membuat baseline pertama sebelum menilai peningkatan.';recommendation='Tentukan perjalanan utama di Funnel, lalu bandingkan metrik yang sama pada periode berikutnya.'}}else if(readiness==='collecting'){headline='Treat this period as an early signal, not a product trend.';meaning=`Only ${fmt(m.users)} ${m.users===1?'person has':'people have'} been observed across ${active} active ${active===1?'day':'days'} of this ${days}-day view. More breadth is needed before comparing product performance.`;recommendation=share>=50&&top?`Inspect ${pretty(top.name)} and confirm that tracking fires once per intended action. Then collect activity from more people and days.`:'Keep collecting activity across more people and days before changing the product.'}else if(share>=50&&top){headline=`${pretty(top.name)} dominates the activity.`;meaning=`It contributes ${share.toFixed(0)}% of all events. A concentrated pattern can mean genuine engagement, repeated behavior, or an event that fires too often.`;recommendation='Inspect the event and the people behind it before treating the volume as product success.'}else if(p.events){const change=(m.events-p.events)/p.events*100;headline=`Activity is ${Math.abs(change).toFixed(0)}% ${change>=0?'higher':'lower'} than the previous period.`;meaning=`The sample is ${readiness==='ready'?'broader than the minimum heuristic':'useful as a directional signal'}, but it is not statistical proof and the contributing events and people still need to be checked.`;recommendation='Open the event stream, identify the main contributors, and validate whether the change supports your product goal.'}else{headline='The sample is broad enough to investigate, but has no previous-period baseline.';meaning='Use event concentration, funnels, and retention to establish the first baseline before judging improvement.';recommendation='Define a key journey in Funnels, then compare the same metric in the next period.'}const delta=p.events?`${percentage(m.events,p.events)} ${t('events').toLowerCase()}`:t('no_baseline');const coverage=state.lang==='id'?`${active} dari ${days} hari`:`${active} of ${days} days`;const evidence=state.lang==='id'?`Satu pengguna menghasilkan ${personShare.toFixed(0)}% aktivitas, sehingga perilaku individu mungkin mendistorsi total.`:`One person generated ${personShare.toFixed(0)}% of activity, so individual behavior may be distorting the total.`;return `<section class="decision-panel"><div class="decision-heading"><div><div class="eyebrow">${t('decision_brief')}</div><h2>${esc(headline)}</h2></div><span class="readiness ${labels[readiness][1]}" title="${t('heuristic')}"><i></i>${labels[readiness][0]}</span></div><div class="decision-signals"><div><span>${t('sample_readiness')}</span><strong>${labels[readiness][0]}</strong></div><div><span>${t('active_coverage')}</span><strong>${coverage}</strong></div><div><span>${t('top_event_share')}</span><strong>${share.toFixed(0)}%</strong></div><div><span>${t('period_comparison')}</span><strong>${esc(delta)}</strong></div></div><div class="decision-body"><div><span class="decision-label">${t('what_means')}</span><p>${esc(meaning)}</p>${personShare>=40?`<p class="decision-evidence">${esc(evidence)}</p>`:''}</div><div class="decision-next"><span class="decision-label">${t('next_action')}</span><p>${esc(recommendation)}</p>${top?`<button class="button primary" data-filter-event="${esc(top.name)}">${t('inspect')} ${esc(pretty(top.name))} →</button>`:`<a class="button primary" href="#events">${t('inspect_stream')} →</a>`}</div></div></section>`}
function spark(values){if(!values.length)return '';const max=Math.max(...values,1);const coords=values.map((v,i)=>`${i*80/Math.max(values.length-1,1)},${34-v/max*28}`).join(' ');return `<svg class="spark" viewBox="0 0 80 40" aria-hidden="true"><path d="M0,40 L${coords.replace(/ /g,' L')} L80,40Z" fill="#f0f6ed"/><polyline points="${coords}" fill="none" stroke="#a0b98f" stroke-width="1.2"/></svg>`}
function stat(label,value,previous,ico,values){return `<div class="stat-card"><div class="stat-label">${icon(ico)} ${label} <i class="info" title="${state.lang==='id'?'Dibandingkan dengan periode sebelumnya dengan durasi yang sama':'Compared with the preceding period of equal length'}">i</i></div><div class="stat-value">${fmt(value)}</div><div class="stat-bottom"><span class="change ${value<previous?'negative':''}">${percentage(value,previous)}</span><span>${t('previous')}</span></div>${spark(values)}</div>`}
function chart(series,metric){metric=metric==='events'?'events':'users';const W=1000,H=205,left=44,right=15,top=18,bottom=30;const rawMax=Math.max(...series.map(d=>d[metric]),1);const step=Math.max(1,Math.ceil(rawMax/4));const max=step*4;const x=i=>left+i*(W-left-right)/Math.max(series.length-1,1);const y=v=>top+(H-top-bottom)*(1-v/max);let grid='';for(let i=0;i<=4;i++){const v=step*i;grid+=`<line x1="${left}" y1="${y(v)}" x2="${W-right}" y2="${y(v)}" stroke="#edf1eb" stroke-dasharray="3 4"/><text x="${left-12}" y="${y(v)+3}" text-anchor="end" fill="#a1aba1" font-size="9">${fmt(v)}</text>`}const coords=series.map((d,i)=>`${x(i)},${y(d[metric])}`).join(' ');let labels='';const stride=Math.max(1,Math.floor(series.length/7));series.forEach((d,i)=>{if(i%stride===0&&i<=series.length-1-stride||i===series.length-1)labels+=`<text x="${x(i)}" y="${H-6}" text-anchor="middle" fill="#a1aba1" font-size="9">${new Date(d.date+'T00:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'})}</text>`});return `<svg class="main-chart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="Daily ${esc(metric)} over the selected period"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#76a98a" stop-opacity=".18"/><stop offset="100%" stop-color="#76a98a" stop-opacity=".015"/></linearGradient></defs>${grid}<path d="M${left},${y(0)} L${coords.replace(/ /g,' L')} L${x(series.length-1)},${y(0)} Z" fill="url(#area)"/><polyline points="${coords}" fill="none" stroke="#4c8d6b" stroke-width="2" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>${labels}${series.map((d,i)=>`<circle cx="${x(i)}" cy="${y(d[metric])}" r="8" fill="transparent"><title>${esc(d.date)}: ${fmt(d[metric])} ${esc(metric)}</title></circle>`).join('')}</svg>`}
let overviewData;
async function overview(){const d=await api(query('/api/overview'));overviewData=d;if(!d.metrics.events)return state.lang==='id'?empty('Cerita produk Anda dimulai dari sebuah event.','Pasang SDK browser atau kirim event pertama melalui API. Insight akan muncul di sini.'):empty('Your product’s story starts with an event.','Install the browser SDK or send your first event through the API. Your insights will appear here.');const m=d.metrics,p=d.previous;const first=d.top_events[0];const page=d.pages[0];const topRate=page?Math.round(page.count/Math.max(m.pageviews,1)*100):0;const demo=state.lang==='id'?'✧ Anda sedang melihat proyek demo. <a href="#setup">Hubungkan produk Anda →</a>':'✧ You’re exploring a seeded demo project. <a href="#setup">Connect your own product →</a>';return `${state.project.name==='Acme Web'?`<div class="demo-notice">${demo}</div>`:''}${decisionBrief(d)}<div class="stat-grid">${stat(t('unique_users'),m.users,p.users,'people',d.series.map(d=>d.users))}${stat(t('total_events'),m.events,p.events,'events',d.series.map(d=>d.events))}${stat(t('sessions'),m.sessions,p.sessions,'grid',d.series.map(d=>d.sessions))}${stat(t('page_views'),m.pageviews,p.pageviews,'overview',d.series.map(d=>d.pageviews))}</div>
<section class="panel"><div class="panel-head"><div><div class="panel-title">${t('activity_time')} <i class="info" title="${state.lang==='id'?'Pengguna unik atau total event, dikelompokkan per hari UTC':'Distinct people or total events, grouped by UTC day'}">i</i></div><p class="panel-subtitle">${t('activity_sub')}</p></div><div class="chart-options"><button class="pill ${state.metric==='users'?'active':''}" data-metric="users">${t('users')}</button><button class="pill ${state.metric==='events'?'active':''}" data-metric="events">${t('events')}</button></div></div><div class="chart-legend"><i></i><span id="legend-metric">${state.metric==='users'?t('unique_users'):t('total_events')}</span><span style="margin-left:auto">${t('daily')}</span></div><div class="chart-wrap" id="activity-chart">${chart(d.series,state.metric)}</div><div class="chart-footer"><span><i></i> ${t('every_action')}</span><a href="#events" class="text-link">${t('explore_events_link')} ↗</a></div></section>
<div class="two-columns"><section class="panel"><div class="panel-head"><div><div class="panel-title">${t('top_events')}</div><p class="panel-subtitle">${state.lang==='id'?'Tindakan yang mendorong produk Anda ke depan.':'The actions moving your product forward.'}</p></div><a href="#events" class="text-link">${state.lang==='id'?'Lihat semua':'View all'} ↗</a></div><table class="data-table"><thead><tr><th>${state.lang==='id'?'Nama event':'Event name'}</th><th class="right">${t('events')}</th><th class="right">${t('users')}</th></tr></thead><tbody>${d.top_events.slice(0,5).map((e,i)=>`<tr><td class="event-name"><button class="event-drilldown" data-filter-event="${esc(e.name)}"><span class="event-symbol ${i===3?'orange':''}">${i===0?'↗':i===1?'♧':i===2?'⊞':i===3?'◇':'ϟ'}</span>${esc(pretty(e.name))}</button></td><td class="right">${fmt(e.count)}</td><td class="right">${fmt(e.users)}</td></tr>`).join('')}</tbody></table></section>
<section class="panel"><div class="panel-head"><div><div class="panel-title">${t('popular_pages')}</div><p class="panel-subtitle">${state.lang==='id'?'Tempat pengguna menghabiskan waktu.':'Where your people spend their time.'}</p></div><a href="#events" class="text-link">${state.lang==='id'?'Jelajahi':'Explore'} ↗</a></div><table class="data-table"><thead><tr><th>${state.lang==='id'?'Path halaman':'Page path'}</th><th>${t('page_views')}</th><th class="right">${state.lang==='id'?'Porsi':'Share'}</th></tr></thead><tbody>${d.pages.slice(0,4).map(e=>`<tr><td class="event-name">${esc(e.name)}</td><td><div class="bar-cell"><span>${fmt(e.count)}</span><span class="bar-track"><span style="width:${Math.round(e.count/Math.max(d.pages[0].count,1)*100)}%"></span></span></div></td><td class="right">${Math.round(e.count/Math.max(m.pageviews,1)*100)}%</td></tr>`).join('')||`<tr><td colspan="3">${state.lang==='id'?'Kirim event $pageview dengan properti $pathname.':'Send $pageview events with a $pathname property.'}</td></tr>`}</tbody></table><div class="mini-insight"><span>✧</span><span>${page?(state.lang==='id'?`<strong>${esc(page.name)}</strong> memperoleh ${topRate}% tampilan halaman. <a class="text-link" href="#funnels">Jelajahi tindakan berikutnya →</a>`:`<strong>${esc(page.name)}</strong> gets ${topRate}% of page views. <a class="text-link" href="#funnels">Explore what people do next →</a>`):(state.lang==='id'?`<strong>${esc(pretty(first.name))}</strong> adalah event teratas. Buat funnel untuk melihat kelanjutannya.`:`<strong>${esc(pretty(first.name))}</strong> is your top event. Build a funnel to see where it leads.`)}</span></div></section></div>
<section class="panel activity-panel"><div class="activity-head"><div class="panel-title">${t('recent_activity')} <span class="live-badge"><i></i> ${t('latest')}</span></div><a href="#events" class="text-link small">${state.lang==='id'?'Lihat aliran event':'View event stream'} ↗</a></div>${eventTable(d.recent.slice(0,4),true)}</section><p class="bottom-note">${state.lang==='id'?'Pertanyaan yang baik menghasilkan produk yang lebih baik. Terus jelajahi.':'Good questions lead to better products. Keep exploring.'}</p>`}
function timeAgo(value){const secs=Math.max(0,Math.round((Date.now()-new Date(value))/1000)),ago=state.lang==='id'?' lalu':' ago',units=state.lang==='id'?['d','m','j']:['s','m','h'];return secs<60?secs+units[0]+ago:secs<3600?Math.floor(secs/60)+units[1]+ago:secs<86400?Math.floor(secs/3600)+units[2]+ago:new Date(value).toLocaleDateString(state.lang==='id'?'id-ID':'en-US',{month:'short',day:'numeric'})}
function eventTable(events,compact=false){state.events=events;const h=state.lang==='id'?['Event','Pengguna','Halaman','Browser','Waktu']:['Event','Person','Page','Browser','Time'];return `<table class="data-table ${compact?'':'full-table'}"><thead><tr><th>${h[0]}</th><th>${h[1]}</th><th class="hide-mobile">${h[2]}</th><th class="hide-mobile">${h[3]}</th><th class="right">${h[4]}</th></tr></thead><tbody>${events.map((e,i)=>`<tr class="clickable" data-event-index="${i}" tabindex="0" aria-label="${state.lang==='id'?'Lihat detail':'View'} ${esc(pretty(e.event))}${state.lang==='id'?'':' details'}"><td class="event-name"><span class="event-symbol">${e.event==='$pageview'?'↗':'ϟ'}</span>${esc(pretty(e.event))}</td><td><button class="person-link" data-person="${esc(e.distinct_id)}">${esc(e.distinct_id)}</button></td><td class="hide-mobile"><span class="tag">${esc(e.properties.$pathname||'—')}</span></td><td class="hide-mobile"><span class="browser-dot">◉</span>${esc(e.properties.$browser||'—')}</td><td class="right" title="${esc(new Date(e.timestamp).toISOString())}">${timeAgo(e.timestamp)}</td></tr>`).join('')||`<tr><td colspan="5" class="empty">${state.lang==='id'?'Tidak ada event yang cocok pada periode ini.':'No matching events in this period.'}</td></tr>`}</tbody></table>`}
async function eventsView(){const q=params();if(state.eventSearch)q.set('q',state.eventSearch);if(state.eventName)q.set('event',state.eventName);q.set('page',state.eventPage);q.set('page_size',state.eventPageSize);const d=await api('/api/events?'+q);state.eventPage=d.page;const id=state.lang==='id',first=d.total?(d.page-1)*d.page_size+1:0,last=Math.min(d.page*d.page_size,d.total);return `<div class="section-tools"><div class="search">${icon('search')}<input id="event-search" aria-label="${id?'Cari event atau pengguna':'Search events or people'}" placeholder="${id?'Cari event atau pengguna…':'Search events or people…'}" value="${esc(state.eventSearch)}"></div><select id="event-filter" aria-label="${id?'Filter event':'Filter event'}"><option value="">${id?'Semua event':'All events'}</option>${d.names.map(e=>`<option value="${esc(e.name)}" ${e.name===state.eventName?'selected':''}>${esc(pretty(e.name))}</option>`).join('')}</select><span class="muted small">${first}–${last} ${id?'dari':'of'} ${fmt(d.total)}</span><button class="button" id="export-events">↓ ${id?'Ekspor JSON':'Export JSON'}</button></div><section class="panel">${eventTable(d.events)}</section>${eventPagination(d,id)}<p class="bottom-note">${id?'Pilih event untuk memeriksa propertinya. Aliran diperbarui setiap 15 detik.':'Select an event to inspect its properties. The stream refreshes every 15 seconds.'}</p>`}
function eventPagination(d,id){if(d.pages<=1)return '';const start=Math.max(1,d.page-2),end=Math.min(d.pages,start+4),buttons=[];for(let page=Math.max(1,end-4);page<=end;page++)buttons.push(`<button class="page-number ${page===d.page?'active':''}" data-event-page="${page}" ${page===d.page?'aria-current="page"':''}>${page}</button>`);return `<nav class="pagination" aria-label="${id?'Halaman event':'Event pages'}"><button class="button" data-event-page="${d.page-1}" ${d.page===1?'disabled':''}>← ${id?'Sebelumnya':'Previous'}</button><div>${buttons.join('')}</div><span>${id?'Halaman':'Page'} ${d.page} / ${d.pages}</span><button class="button" data-event-page="${d.page+1}" ${d.page===d.pages?'disabled':''}>${id?'Berikutnya':'Next'} →</button></nav>`}
async function people(){const list=await api(query('/api/people'));const filtered=list.filter(p=>p.id.toLowerCase().includes(state.peopleSearch.toLowerCase()));return `<div class="section-tools"><div class="search">${icon('search')}<input id="people-search" aria-label="Search people" placeholder="Find a person…" value="${esc(state.peopleSearch)}"></div><span class="muted small">${fmt(filtered.length)} people in this period</span></div><section class="panel"><table class="data-table full-table"><thead><tr><th>Person</th><th class="right">Events</th><th>Plan</th><th class="hide-mobile">Device</th><th class="right">Last seen</th></tr></thead><tbody>${filtered.map(p=>`<tr><td><button class="person-link" data-person="${esc(p.id)}"><span class="event-symbol">♧</span>${esc(p.id)}</button></td><td class="right">${fmt(p.events)}</td><td><span class="tag green">${esc(p.properties.plan||'—')}</span></td><td class="hide-mobile">${esc(p.properties.$device||'—')}</td><td class="right">${timeAgo(p.last_seen)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No people found in this period.</td></tr>'}</tbody></table></section><p class="bottom-note">People are grouped by distinct_id. Use pulse.identify() to connect activity to your users.</p>`}
async function funnels(){const d=await api(query('/api/overview'));const names=d.top_events.map(e=>e.name);if(names.length<2)return empty('Find where the journey gets stuck.','Track at least two different events to build your first conversion funnel.');if(!state.steps.length||state.steps.some(s=>!names.includes(s))){state.steps=['$pageview','signed_up','project_created','subscription_started'].filter(s=>names.includes(s));if(state.steps.length<2)state.steps=names.slice(0,3)}const q=params();state.steps.forEach(s=>q.append('step',s));const f=await api('/api/funnel?'+q);state.funnel=f;const largest=f.slice(1).reduce((best,s)=>s.dropoff>best.dropoff?s:best,{dropoff:0});const conversion=f.at(-1).rate;return `<section class="panel"><div class="panel-head"><div><div class="panel-title">The path to value</div><p class="panel-subtitle">Unique people · ordered steps · 7-day conversion window</p></div><span class="tag green">${conversion.toFixed(1)}% conversion</span></div><div class="funnel-controls">${state.steps.map((step,i)=>`<select class="funnel-select" data-step="${i}" aria-label="Funnel step ${i+1}">${names.map(n=>`<option value="${esc(n)}" ${n===step?'selected':''}>${i+1}. ${esc(pretty(n))}</option>`).join('')}</select>${i<state.steps.length-1?'<span class="muted">→</span>':''}`).join('')}${state.steps.length<6?'<button class="button" id="add-step">＋ Step</button>':''}${state.steps.length>2?'<button class="button" id="remove-step">− Step</button>':''}</div><div class="funnel-chart">${f.map((s,i)=>`<div class="funnel-column"><button class="funnel-value funnel-drilldown" data-funnel-index="${i}" aria-label="Inspect people at ${esc(pretty(s.name))}">${fmt(s.users)}<small>${s.rate.toFixed(1)}%</small></button><div class="funnel-bar" style="height:${Math.max(2,s.rate*1.7)}px"></div><div class="funnel-step"><span>${i+1}</span>${esc(pretty(s.name))}</div>${i&&s.dropoff?`<button class="dropoff-link" data-funnel-dropoff="${i}">${fmt(s.dropoff)} people dropped off</button>`:'<p class="muted small">Entered the funnel</p>'}</div>`).join('')}</div><div class="mini-insight"><span>✧</span><span>${largest.dropoff?`Your biggest opportunity is before <strong>${esc(pretty(largest.name))}</strong>. ${fmt(largest.dropoff)} people didn’t reach this step. Inspect these users’ activity to understand the friction.`:'No drop-off between these steps in the selected period. Try a different journey or date range.'}</span></div></section><p class="bottom-note">Select a count or drop-off to inspect the people behind it. Each person counts once per step.</p>`}
async function retention(){const rows=await api(query('/api/retention'));const cohorts=rows.filter(c=>c.size>0).slice(-14);if(!cohorts.length)return empty('Make the first visit the start of something.','Retention cohorts appear when new people send their first events. Try a wider date range.');return `<section class="panel"><div class="panel-head"><div><div class="panel-title">Do your people come back?</div><p class="panel-subtitle">Daily cohorts · first-ever activity → any returning activity · last 14 non-empty cohorts</p></div><span class="tag">Daily retention</span></div><div style="overflow:auto"><table class="data-table retention-table"><thead><tr><th>First seen</th><th>People</th>${Array.from({length:8},(_,i)=>`<th>Day ${i}</th>`).join('')}</tr></thead><tbody>${cohorts.map(c=>`<tr><td>${esc(c.date)}</td><td>${fmt(c.size)}</td>${c.retained.map(p=>`<td><div class="retention-cell" style="background:${p===null?'#f5f7f3':`rgba(55,130,84,${.06+p/150})`};color:${p>60?'white':'#64816b'};padding:10px 3px" title="${p===null?'Not yet observable':p.toFixed(1)+'% of the cohort returned'}">${p===null?'—':p.toFixed(0)+'%'}</div></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="mini-insight"><span>✧</span><span>A darker cell means more people came back. Compare cohorts to see whether product changes are building a stronger habit. A dash means the day is not observable or the cohort is empty.</span></div></section><p class="bottom-note">Cohorts use first activity across the full project history. Today’s results are still partial.</p>`}
async function paths(){const rows=await api(query('/api/paths'));if(!rows.length)return empty('A journey needs more than one step.','Collect consecutive events from the same people to reveal the routes through your product.','Check event stream','events');const max=rows[0].count;return `<section class="panel paths-panel"><div class="panel-head"><div><div class="panel-title">Most common transitions</div><p class="panel-subtitle">Consecutive actions by the same person in the selected period</p></div><span class="tag">Top ${rows.length}</span></div><div class="path-list">${rows.map((edge,index)=>`<button class="path-row" data-path-from="${esc(edge.from)}" data-path-to="${esc(edge.to)}"><span class="path-rank">${index+1}</span><span class="path-node">${esc(pretty(edge.from))}</span><span class="path-line"><i style="width:${Math.max(8,edge.count/max*100)}%"></i><b>→</b></span><span class="path-node">${esc(pretty(edge.to))}</span><span class="path-count"><strong>${fmt(edge.users)}</strong> people<br><small>${fmt(edge.count)} transitions</small></span></button>`).join('')}</div><div class="mini-insight"><span>✧</span><span>Use paths to discover behavior, then turn a promising route into a funnel and measure its conversion.</span></div></section>`}

async function health(){const d=await api(query('/api/catalog'));if(!d.events)return empty('Waiting for the first signal.','Send a test event to verify that Pulse can receive activity from this product.','Open setup guide','setup');const warningCount=d.definitions.reduce((n,event)=>n+event.warnings.length,0);const status=warningCount?'Review needed':'Healthy';return `<div class="health-hero"><div><span class="health-pulse"><i></i>${status}</span><h2>${warningCount?`${warningCount} instrumentation ${warningCount===1?'warning':'warnings'} need attention.`:'Your tracking is consistent in this period.'}</h2><p>Pulse checked event shapes, identity coverage, and session coverage across the selected period.</p></div><div class="health-score">${Math.max(0,100-warningCount*10)}<small>/100</small></div></div><div class="stat-grid health-stats">${stat('Events received',d.events,0,'events',[])}${stat('Event types',d.event_types,0,'grid',[])}${stat('Identified activity',Math.round(d.identified_rate),0,'people',[])}${stat('Session coverage',Math.round(d.session_rate),0,'clock',[])}</div><section class="panel"><div class="panel-head"><div><div class="panel-title">Event catalog</div><p class="panel-subtitle">What Pulse has received and whether its properties stay consistent.</p></div><a href="#setup" class="text-link">Tracking guide ↗</a></div><table class="data-table full-table"><thead><tr><th>Event</th><th class="right">Volume</th><th class="right">People</th><th>Properties</th><th>Last seen</th><th>Status</th></tr></thead><tbody>${d.definitions.map(event=>`<tr><td class="event-name"><button class="event-drilldown" data-filter-event="${esc(event.name)}"><span class="event-symbol">ϟ</span>${esc(pretty(event.name))}</button></td><td class="right">${fmt(event.count)}</td><td class="right">${fmt(event.users)}</td><td><span class="property-summary" title="${esc(Object.entries(event.properties).map(([k,v])=>`${k}: ${v}`).join('\n'))}">${fmt(Object.keys(event.properties).length)} properties</span></td><td>${timeAgo(event.last_seen)}</td><td>${event.warnings.length?`<span class="tag warning" title="${esc(event.warnings.join(', '))}">Review</span>`:'<span class="tag green">Consistent</span>'}</td></tr>`).join('')}</tbody></table></section>`}

async function saveCurrent(){const config={view:state.view,days:state.days,metric:state.metric,eventName:state.eventName,steps:[...state.steps],property:state.segmentProperty,value:state.segmentValue};await api(`/api/reports?project=${encodeURIComponent(state.project.id)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:pageConfig(state.view)[1],type:state.view,config})});toast('Analysis saved for your team.');}
async function savedAnalyses(){const items=await api(`/api/reports?project=${encodeURIComponent(state.project.id)}`);state.reports=items;if(!items.length)return empty('Save the questions you return to.','Open an analysis, set its date range or segment, and choose Save analysis.','Open product overview','overview');return `<section class="panel"><div class="panel-head"><div><div class="panel-title">Saved analyses</div><p class="panel-subtitle">Shared with everyone who has access to this workspace.</p></div><span class="tag">${items.length} saved</span></div><div class="saved-list">${items.map(item=>{const c=item.config||{};return `<div class="saved-row"><button class="saved-main" data-open-saved="${esc(item.id)}"><span class="event-symbol">✧</span><span><strong>${esc(item.name)}</strong><small>${c.days||30} days${c.property?` · ${esc(c.property)} = ${esc(c.value)}`:''} · by ${esc(item.created_by)}</small></span></button><time>${timeAgo(item.updated_at)}</time>${state.user?.role==='viewer'?'':`<button class="icon-button" data-delete-saved="${esc(item.id)}" aria-label="Delete saved analysis">×</button>`}</div>`}).join('')}</div></section>`}

async function workspace(){
 const project=encodeURIComponent(state.project.id),canEdit=state.user?.role!=='viewer',isOwner=state.user?.role==='owner';
 const requests=[api(`/api/reports?project=${project}`),api(`/api/dashboards?project=${project}`),api(query('/api/annotations')),api(`/api/alerts?project=${project}`)];
 if(isOwner)requests.push(api('/api/access-tokens'),api('/api/audit?limit=20'));
 const [reports,dashboards,annotations,alerts,tokens=[],audit=[]]=await Promise.all(requests);state.reports=reports;
 const team=isOwner?`<section class="panel workspace-card"><div class="panel-head"><div><div class="panel-title">Team access</div><p class="panel-subtitle">Issue a separate, revocable token for every teammate or integration.</p></div><span class="tag">Owner only</span></div><form id="token-form" class="inline-form"><input name="name" maxlength="80" required placeholder="Teammate or integration"><select name="role"><option value="viewer">Viewer</option><option value="editor">Editor</option><option value="owner">Owner</option></select><button class="button primary">Create access</button></form><div class="compact-list">${tokens.map(item=>`<div><span><strong>${esc(item.name)}</strong><small>${esc(item.role)} · ${item.last_used_at?'used '+timeAgo(item.last_used_at):'never used'}</small></span>${item.revoked_at?'<span class="tag">Revoked</span>':`<button class="text-link" data-revoke-token="${esc(item.id)}">Revoke</button>`}</div>`).join('')||'<p>No team tokens yet.</p>'}</div></section>`:`<section class="panel workspace-card"><div class="panel-title">Your access</div><p>You are signed in as <strong>${esc(state.user?.name)}</strong> with the <span class="tag">${esc(state.user?.role)}</span> role.</p><p class="panel-subtitle">An owner can issue or revoke workspace access.</p></section>`;
 const shared=`<section class="panel workspace-card"><div class="panel-head"><div><div class="panel-title">Shared dashboards</div><p class="panel-subtitle">Group saved analyses into a durable team view.</p></div><span class="tag">${dashboards.length}</span></div>${canEdit?`<form id="dashboard-form" class="stack-form"><input name="name" maxlength="120" required placeholder="Dashboard name"><div class="check-grid">${reports.map(r=>`<label><input type="checkbox" name="report_ids" value="${esc(r.id)}"> ${esc(r.name)}</label>`).join('')||'<small>Save an analysis first.</small>'}</div><button class="button">Create dashboard</button></form>`:''}<div class="compact-list">${dashboards.map(d=>`<div><span><strong>${esc(d.name)}</strong><small>${d.report_ids.length} reports · by ${esc(d.created_by)}</small></span>${canEdit?`<button class="text-link" data-delete-dashboard="${esc(d.id)}">Delete</button>`:''}</div>`).join('')||'<p>No shared dashboards yet.</p>'}</div></section>`;
 const context=`<section class="panel workspace-card"><div class="panel-head"><div><div class="panel-title">Timeline annotations</div><p class="panel-subtitle">Explain releases, campaigns, and incidents beside the data.</p></div><span class="tag">${annotations.length}</span></div>${canEdit?`<form id="annotation-form" class="stack-form"><input name="title" maxlength="120" required placeholder="What changed?"><input name="occurred_at" type="datetime-local" required><textarea name="description" maxlength="2000" rows="2" placeholder="Optional context"></textarea><button class="button">Add annotation</button></form>`:''}<div class="compact-list">${annotations.map(a=>`<div><span><strong>${esc(a.title)}</strong><small>${new Date(a.occurred_at).toLocaleString()} · ${esc(a.created_by)}</small></span>${canEdit?`<button class="text-link" data-delete-annotation="${esc(a.id)}">Delete</button>`:''}</div>`).join('')||'<p>No annotations in this date range.</p>'}</div></section>`;
 const monitoring=`<section class="panel workspace-card"><div class="panel-head"><div><div class="panel-title">Metric alerts</div><p class="panel-subtitle">Define thresholds now; alerts are evaluated whenever monitoring runs.</p></div><span class="tag">${alerts.length}</span></div>${canEdit?`<form id="alert-form" class="inline-form"><input name="name" required maxlength="120" placeholder="Alert name"><select name="metric"><option>users</option><option>events</option><option>sessions</option><option>pageviews</option></select><select name="comparison"><option value="below">falls below</option><option value="above">rises above</option><option value="changes_by">changes by</option></select><input name="threshold" type="number" required step="any" placeholder="Value"><button class="button">Add</button></form>`:''}<div class="compact-list">${alerts.map(a=>`<div><span><strong>${esc(a.name)}</strong><small>${esc(a.metric)} ${esc(a.comparison.replace('_',' '))} ${a.threshold}</small></span>${canEdit?`<button class="text-link" data-delete-alert="${esc(a.id)}">Delete</button>`:''}</div>`).join('')||'<p>No alert rules yet.</p>'}</div></section>`;
 const history=isOwner?`<section class="panel workspace-card wide"><div class="panel-head"><div><div class="panel-title">Recent workspace activity</div><p class="panel-subtitle">A record of administrative and collaborative changes.</p></div></div><div class="compact-list">${audit.map(a=>`<div><span><strong>${esc(a.action.replaceAll('.',' · '))}</strong><small>${esc(a.actor)} · ${timeAgo(a.created_at)}</small></span><code>${esc(a.target_id||a.project_id||'')}</code></div>`).join('')||'<p>No administrative changes yet.</p>'}</div></section>`:'';
 return `<div class="workspace-intro"><span class="tag green">${esc(state.user?.role||'viewer')}</span><p>Changes here are shared across browsers and recorded for accountability.</p></div><div class="workspace-grid">${team}${shared}${context}${monitoring}${history}</div>`
}

async function guide(){
 const id=state.lang==='id';
 const steps=id?[
  ['Hubungkan produk','Buat proyek, daftarkan origin aplikasi, lalu pasang SDK atau kirim event melalui API.','setup','Buka panduan instalasi'],
  ['Periksa kualitas data','Pastikan nama event, identitas pengguna, sesi, dan properti konsisten sebelum mengambil keputusan.','health','Periksa tracking'],
  ['Ajukan satu pertanyaan','Mulai dari Ringkasan, lalu gunakan filter properti dan rentang waktu untuk mempersempit konteks.','overview','Jelajahi ringkasan'],
  ['Temukan titik hambatan','Gunakan Paths untuk menemukan perjalanan nyata, Funnel untuk mengukur konversi, dan Retensi untuk melihat kebiasaan.','funnels','Buat funnel'],
  ['Bagikan keputusan','Simpan analisis, kelompokkan ke dashboard, dan tambahkan anotasi agar tim memahami perubahan pada data.','workspace','Buka ruang kerja']
 ]:[
  ['Connect your product','Create a project, allow your app origin, then install the SDK or send events through the API.','setup','Open installation guide'],
  ['Verify the signal','Check event names, user identity, sessions, and property consistency before making decisions.','health','Check tracking health'],
  ['Ask one question','Start in Overview, then narrow the context with a date range and an exact property filter.','overview','Explore overview'],
  ['Find the friction','Use Paths to discover real journeys, Funnels to measure conversion, and Retention to see whether habits form.','funnels','Build a funnel'],
  ['Share the decision','Save analyses, group them into dashboards, and add annotations so the team understands changes in the data.','workspace','Open workspace']
 ];
 const glossary=id?[['Event','Tindakan yang dilakukan pengguna, misalnya signed_up.'],['Person','Pengguna yang dikelompokkan berdasarkan distinct_id.'],['Property','Konteks tambahan seperti plan, browser, atau halaman.'],['Session','Sekumpulan aktivitas dengan session_id yang sama.']]:[['Event','An action a person takes, such as signed_up.'],['Person','A user grouped by a stable distinct_id.'],['Property','Extra context such as plan, browser, or page.'],['Session','A group of activity sharing the same session_id.']];
 const securityGuide=id?[
  ['Akses dan peran','Viewer dapat membaca analitik. Editor juga dapat menyimpan analisis, dashboard, anotasi, definisi event, dan alert. Owner dapat membuat proyek, menerbitkan atau mencabut token, mengatur retensi, dan melakukan penghapusan permanen. Gunakan token terpisah untuk setiap rekan atau integrasi.'],
  ['Batas kapasitas','Setiap workspace dibatasi hingga 100 proyek dan 100 catatan token akses. Setiap jenis data kolaborasi dibatasi hingga 1.000 catatan per proyek. Properti event dibatasi 64 KiB dan satu kueri berhenti setelah 32 MiB data event. Permintaan capture tetap dibatasi 1 MiB dan 100 event.'],
  ['Retensi dan penghapusan','Retensi event dijalankan saat startup dan setiap 24 jam. Token yang dicabut disimpan 90 hari dan audit workspace 365 hari secara default; keduanya dapat diubah melalui environment. Penghapusan person mengikuti tautan identitas anonim ke teridentifikasi agar seluruh event yang terhubung ikut dihapus. Backup database harus memiliki kebijakan retensi terpisah.'],
  ['Browser dan deployment','Cookie aman aktif secara default. Mode cookie tidak aman hanya untuk loopback. Untuk akses jarak jauh, gunakan reverse proxy TLS yang mempertahankan Host dan batasi endpoint operasional sesuai kebutuhan. CSP membatasi script, framing, form, base URL, dan object; origin browser harus didaftarkan secara tepat.'],
  ['Operasi dan upgrade','Migrasi database berjalan otomatis dan dikunci agar aman pada beberapa instance. Pantau /healthz dan /readyz, buat backup PostgreSQL, uji pemulihan, dan tingkatkan batas hanya bersama kapasitas database, memori, ingress, serta monitoring. Setelah upgrade, jalankan pengujian dan verifikasi migrasi sebelum memperluas trafik.']
 ]:[
  ['Access and roles','Viewers can read analytics. Editors can also save analyses, dashboards, annotations, event definitions, and alerts. Owners can create projects, issue or revoke tokens, configure retention, and perform permanent deletion. Give every teammate or integration a separate token.'],
  ['Capacity boundaries','Each workspace is capped at 100 projects and 100 stored access-token records. Each collaboration resource is capped at 1,000 records per project. Event properties are capped at 64 KiB and a query stops after 32 MiB of event data. Capture requests remain capped at 1 MiB and 100 events.'],
  ['Retention and deletion','Event retention runs at startup and every 24 hours. Revoked tokens are retained for 90 days and workspace audits for 365 days by default; both are configurable through the environment. Person deletion follows anonymous-to-identified identity links so connected events are removed together. Database backups require a separate retention policy.'],
  ['Browser and deployment','Secure cookies are on by default, and insecure-cookie mode is loopback-only. Remote access requires a TLS reverse proxy that preserves Host; restrict operational endpoints when appropriate. CSP constrains scripts, framing, forms, base URLs, and objects, and browser origins must be registered exactly.'],
  ['Operations and upgrades','Database migrations run automatically under a cross-instance lock. Monitor /healthz and /readyz, back up PostgreSQL, test restores, and raise limits only with matching database, memory, ingress, and monitoring capacity. After an upgrade, run tests and verify migrations before expanding traffic.']
 ];
 const featureGuide=id?[
  ['Ringkasan','Gunakan untuk melihat keadaan produk secara cepat: pengguna unik, event, sesi, page view, tren harian, event teratas, dan halaman populer. Bandingkan dengan periode sebelumnya, lalu buka event yang terlihat tidak biasa.','overview'],
  ['Event Explorer','Gunakan untuk memeriksa data mentah. Cari nama event, pilih jenis event, buka satu baris untuk melihat person, session, waktu, dan properties. Pagination menjaga daftar tetap ringan; export mengikuti rentang tanggal dan filter aktif.','events'],
  ['People','Gunakan untuk memahami aktivitas per distinct_id. Cari person, lihat event terakhir dan properties terbaru, lalu buka timeline untuk memeriksa urutan perilaku. Setelah login, panggil identify dengan ID yang stabil agar aktivitas berikutnya konsisten.','people'],
  ['Funnels','Pilih dua hingga delapan langkah berurutan untuk melihat berapa orang mencapai setiap langkah dalam jendela tujuh hari. Klik jumlah selesai atau drop-off untuk melihat daftar person. Gunakan event yang mewakili nilai, bukan event teknis yang terlalu sering.','funnels'],
  ['Retention','Menunjukkan cohort berdasarkan event pertama setiap person dan persentase yang kembali pada hari berikutnya. Gunakan rentang yang cukup panjang, bandingkan cohort, dan periksa perubahan produk atau kampanye sebelum menyimpulkan sebab.','retention'],
  ['Paths','Merangkum urutan event yang benar-benar terjadi di dalam session. Gunakan untuk menemukan jalur umum, langkah yang tidak terduga, atau jalan buntu sebelum membangun funnel yang lebih spesifik.','paths'],
  ['Tracking Health','Memeriksa volume, jenis event, penggunaan session, konsistensi properties, dan sinyal kualitas lainnya. Buka halaman ini setelah memasang SDK, setelah release, atau ketika angka berubah tiba-tiba.','health'],
  ['Saved Analyses','Simpan kondisi analisis saat ini—halaman, tanggal, metrik, funnel, dan segment—agar tim dapat membuka pertanyaan yang sama. Konfigurasi divalidasi; hapus analisis yang tidak lagi dipakai agar workspace tetap jelas.','saved'],
  ['Workspace','Editor dan owner dapat membuat dashboard, anotasi timeline, definisi event, dan alert. Owner juga mengelola token akses dan melihat audit terbaru. Gunakan anotasi untuk release, kampanye, dan insiden yang dapat menjelaskan perubahan data.','workspace'],
  ['Project Settings','Atur nama, exact browser origins, ingestion key, retensi event, export, penghapusan person, dan penghapusan proyek. Rotasi key menghentikan instalasi lama sampai key baru dipasang. Tindakan penghapusan tidak dapat dibatalkan.','settings'],
  ['Setup dan SDK','Buat satu proyek per produk atau lingkungan yang perlu dipisahkan. Browser SDK mengirim page view pertama, capture mengirim tindakan penting, page dipanggil setelah navigasi SPA, reset dipanggil saat logout, dan optOut menghentikan pengumpulan.','setup'],
  ['Filter dan rentang waktu','Rentang tanggal berlaku pada laporan aktif. Segment property menggunakan kecocokan exact property/value. Mulai tanpa filter, tambahkan satu filter, lalu bandingkan hasil agar Anda tahu perubahan mana yang berasal dari segment.','overview']
 ]:[
  ['Overview','Use this for a fast product read: unique people, events, sessions, page views, daily trends, top events, and popular pages. Compare with the previous period, then inspect any event that looks unusual.','overview'],
  ['Event Explorer','Use this to inspect raw data. Search event names, select an event type, and open a row to see the person, session, timestamp, and properties. Pagination keeps the list bounded; export follows the active date range and filters.','events'],
  ['People','Use this to understand activity by distinct_id. Search for a person, review their latest event and properties, then open the timeline to inspect behavior in order. After sign-in, call identify with a stable ID so future activity remains consistent.','people'],
  ['Funnels','Choose two to eight ordered steps to see how many people complete each step within seven days. Click completed or drop-off counts to inspect people. Prefer events that represent value over noisy technical events.','funnels'],
  ['Retention','Cohorts people by their first event and shows the percentage who return on later days. Use a sufficiently long range, compare cohorts, and check product releases or campaigns before attributing a cause.','retention'],
  ['Paths','Summarizes event sequences that actually occurred inside sessions. Use it to discover common journeys, unexpected steps, or dead ends before defining a more specific funnel.','paths'],
  ['Tracking Health','Reviews volume, event types, session coverage, property consistency, and other quality signals. Check it after installing the SDK, after a release, or whenever metrics change unexpectedly.','health'],
  ['Saved Analyses','Save the current page, date range, metric, funnel, and segment so the team can reopen the same question. Configurations are validated; delete analyses that no longer help keep the workspace clear.','saved'],
  ['Workspace','Editors and owners can create dashboards, timeline annotations, event definitions, and alerts. Owners also manage access tokens and inspect recent audit activity. Annotate releases, campaigns, and incidents that may explain changes.','workspace'],
  ['Project Settings','Manage the name, exact browser origins, ingestion key, event retention, export, person deletion, and project deletion. Rotating the key stops old installations until the new key is deployed. Deletion actions are irreversible.','settings'],
  ['Setup and SDK','Create one project per product or environment that needs isolation. The browser SDK sends the first page view, capture records meaningful actions, page follows SPA navigation, reset runs on sign-out, and optOut stops collection.','setup'],
  ['Filters and date ranges','The date range applies to the active report. Property segments use exact property/value matching. Start unfiltered, add one filter, and compare the result so you understand what the segment changed.','overview']
 ];
 const firstRun=id?['Buat proyek dan daftarkan exact origin browser.','Pasang SDK atau kirim satu event backend dengan ID stabil.','Buka Tracking Health dan pastikan event, identity, session, dan properties benar.','Buka Event Explorer dan periksa beberapa event mentah.','Ajukan satu pertanyaan di Overview, Funnel, Retention, atau Paths.','Simpan analisis dan tambahkan anotasi jika hasil akan dibagikan.']:['Create a project and register the exact browser origin.','Install the SDK or send one backend event with a stable ID.','Open Tracking Health and verify events, identity, sessions, and properties.','Open Event Explorer and inspect several raw events.','Ask one question in Overview, Funnels, Retention, or Paths.','Save the analysis and add an annotation when the result will be shared.'];
 const troubleshooting=id?[
  ['Tidak ada data','Periksa project yang dipilih, rentang tanggal, filter, ingestion key, origin, dan respons /capture. Gunakan Tracking Health serta Event Explorer sebelum memeriksa laporan turunan.'],
  ['Jumlah person terlalu besar','Pastikan identify memakai ID stabil setelah login, reset dipanggil saat logout, dan anonymous ID tidak dibuat ulang pada setiap page view.'],
  ['Funnel tampak rendah','Pastikan nama dan urutan langkah benar, semua langkah terjadi dalam tujuh hari, dan segment yang aktif memang memiliki property pada setiap event yang diperlukan.'],
  ['Angka berubah setelah filter','Segment diterapkan dengan exact match. Periksa ejaan, tipe nilai, kapitalisasi, serta apakah property tersedia pada event dalam laporan.'],
  ['Permintaan ditolak','HTTP 413 berarti request, properties, query, atau koleksi melewati batas aman. HTTP 429 berarti quota event atau workspace tercapai. Persempit kueri atau hapus data yang tidak dipakai sebelum menaikkan kapasitas.']
 ]:[
  ['No data appears','Check the selected project, date range, filters, ingestion key, browser origin, and /capture response. Use Tracking Health and Event Explorer before debugging derived reports.'],
  ['Person counts look inflated','Confirm identify uses a stable ID after sign-in, reset runs at sign-out, and the anonymous ID is not recreated on every page view.'],
  ['Funnel conversion looks low','Verify step names and order, that all steps occur within seven days, and that the active segment property exists on every required event.'],
  ['Numbers change after filtering','Segments use exact matching. Check spelling, value type, capitalization, and whether the property exists on events used by the report.'],
  ['A request is rejected','HTTP 413 means a request, properties object, query, or collection exceeded a safety bound. HTTP 429 means an event or workspace quota was reached. Narrow the query or remove unused data before raising capacity.']
 ];
 return `<div class="guide-hero"><div><span class="guide-mark">ϟ</span><h2>${id?'Pulse membantu Anda bergerak dari aktivitas ke keputusan.':'Pulse helps you move from activity to a decision.'}</h2><p>${id?'Alur terbaik bukan membuka setiap laporan. Mulai dengan satu pertanyaan produk, pastikan datanya sehat, lalu ikuti bukti.':'The best workflow is not opening every report. Start with one product question, verify the data, then follow the evidence.'}</p></div><a class="button primary" href="#${state.project?'overview':'setup'}">${id?'Mulai menjelajah':'Start exploring'} →</a></div><div class="guide-layout"><nav class="guide-index" aria-label="${id?'Isi panduan':'Guide contents'}"><strong>${id?'Alur kerja':'Workflow'}</strong>${steps.map((step,i)=>`<a href="#guide-step-${i+1}"><span>${i+1}</span>${esc(step[0])}</a>`).join('')}<strong>${id?'Panduan fitur':'Feature manual'}</strong>${featureGuide.map((item,i)=>`<a href="#guide-feature-${i+1}"><span>${i+1}</span>${esc(item[0])}</a>`).join('')}<strong>${id?'Konsep utama':'Core concepts'}</strong>${glossary.map(item=>`<span class="guide-term">${esc(item[0])}</span>`).join('')}<strong>${id?'Keamanan dan operasi':'Security and operations'}</strong>${securityGuide.map((item,i)=>`<a href="#guide-security-${i+1}"><span>${i+1}</span>${esc(item[0])}</a>`).join('')}</nav><main class="guide-story">${steps.map((step,i)=>`<section id="guide-step-${i+1}" class="guide-step"><div class="guide-number">${String(i+1).padStart(2,'0')}</div><div><h3>${esc(step[0])}</h3><p>${esc(step[1])}</p><a href="#${step[2]}" class="text-link">${esc(step[3])} →</a></div></section>`).join('')}<section class="guide-glossary"><h3>${id?'Bahasa Pulse':'The language of Pulse'}</h3><div>${glossary.map(item=>`<article><strong>${esc(item[0])}</strong><p>${esc(item[1])}</p></article>`).join('')}</div></section><section class="guide-manual"><div class="guide-manual-head"><span>?</span><div><h3>${id?'Panduan setiap fitur':'Feature-by-feature manual'}</h3><p>${id?'Apa fungsi setiap halaman, kapan digunakan, dan tindakan berikutnya.':'What each page does, when to use it, and what to do next.'}</p></div></div>${featureGuide.map((item,i)=>`<article id="guide-feature-${i+1}"><div><span>${String(i+1).padStart(2,'0')}</span><h4>${esc(item[0])}</h4></div><p>${esc(item[1])}</p><a class="text-link" href="#${item[2]}">${id?'Buka halaman':'Open page'} →</a></article>`).join('')}</section><section class="guide-help-grid"><article><h3>${id?'Checklist pertama kali':'First-run checklist'}</h3><ol>${firstRun.map(item=>`<li>${esc(item)}</li>`).join('')}</ol></article><article><h3>${id?'Pemecahan masalah':'Troubleshooting'}</h3>${troubleshooting.map(item=>`<details><summary>${esc(item[0])}</summary><p>${esc(item[1])}</p></details>`).join('')}</article></section><section class="guide-security"><div class="guide-security-head"><span>⌾</span><div><h3>${id?'Keamanan, privasi, dan operasi':'Security, privacy, and operations'}</h3><p>${id?'Batas berikut adalah bagian dari kontrak produk, bukan sekadar saran deployment.':'These boundaries are part of the product contract, not only deployment advice.'}</p></div></div>${securityGuide.map((item,i)=>`<article id="guide-security-${i+1}"><span>${String(i+1).padStart(2,'0')}</span><div><h4>${esc(item[0])}</h4><p>${esc(item[1])}</p></div></article>`).join('')}<div class="guide-config"><strong>${id?'Konfigurasi retensi':'Retention configuration'}</strong><code>PULSE_AUDIT_RETENTION_DAYS=365</code><code>PULSE_REVOKED_TOKEN_RETENTION_DAYS=90</code></div></section><section class="guide-principle"><span>✧</span><div><h3>${id?'Prinsip sederhana':'A useful rule'}</h3><p>${id?'Volume menjelaskan apa yang terjadi. Funnel dan retensi membantu menjelaskan apakah pengguna menemukan nilai. Selalu periksa pengguna dan event di balik angkanya.':'Volume tells you what happened. Funnels and retention help you judge whether people found value. Always inspect the people and events behind the number.'}</p></div></section></main></div>`
}

function snippet(code){return `<div class="code-wrap"><button class="copy-button" data-copy>Copy</button><pre><code>${esc(code)}</code></pre></div>`}
async function setup(){const host=location.origin,key=state.project.key;return `<div class="setup-grid"><section class="panel"><div class="setup-step"><div class="step-title"><span class="step-number">1</span> Install the browser SDK</div><p>Add this before the closing &lt;/body&gt; tag in your product. It tracks the first page view automatically.</p>${snippet(`<script src="${host}/sdk.js"></script>\n<script>\n  pulse.init('${key}', {\n    host: '${host}'\n  });\n</script>`)}</div><div class="setup-step"><div class="step-title"><span class="step-number">2</span> Track the moments that matter</div><p>Identify a person after sign-in and capture meaningful product actions. For single-page apps, call pulse.page() after navigation.</p>${snippet(`pulse.identify('user_123', { plan: 'Pro' });\npulse.capture('project_created', { source: 'onboarding' });\npulse.capture('subscription_started', { plan: 'Pro' });\npulse.page();\n// On sign-out: pulse.reset();`)}</div><div class="setup-step"><div class="step-title"><span class="step-number">3</span> Or send events from your backend</div><p>Use the same HTTP endpoint from Go, Node, Python, or any other service. Supply a stable event ID to safely retry.</p>${snippet(`curl ${host}/capture \\\n  -H 'Content-Type: application/json' \\\n  -d '{\n    "api_key": "${key}",\n    "events": [{\n      "id": "order-123-paid",\n      "event": "subscription_started",\n      "distinct_id": "user_123",\n      "properties": {"plan": "Pro"}\n    }]\n  }'`)}</div></section><aside><section class="panel setup-aside"><span class="signal-icon">✧</span><h3>A separate space for every product.</h3><p>Each project has its own public ingestion key. Events, people, and insights stay scoped to that product.</p><h3>A little care goes a long way.</h3><ul><li>Allow your product’s exact browser origin when creating a project.</li><li>Event collection uses no cookies and respects Do Not Track by default.</li><li>Call pulse.optOut() to stop collection and clear queued events.</li><li>Avoid sending passwords, payment details, or personal data you don’t need.</li><li>Identify links earlier anonymous activity to the stable signed-in ID in reports. Call reset on sign-out.</li></ul><p>Public ingestion keys can send events. Keep your administrator token on your server.</p><a href="#events" class="button">Check your event stream →</a></section></aside></div>`}
async function settings(){const owner=state.user?.role==='owner',editor=state.user?.role!=='viewer';return `<section class="panel"><div class="panel-head"><div><div class="panel-title">Project details</div><p class="panel-subtitle">Signed in as ${esc(state.user?.name)} · ${esc(state.user?.role)}</p></div></div><div class="settings-body"><div class="settings-row"><label>Project name</label><input id="settings-name" aria-label="Project name" value="${esc(state.project.name)}" maxlength="80" ${editor?'':'disabled'}></div><div class="settings-row"><label>Project ID</label><div class="settings-value">${esc(state.project.id)}</div></div><div class="settings-row"><label>Public ingestion key</label>${snippet(state.project.key)}<p>This key can only send events. It cannot read your analytics.</p>${owner?'<button class="button" id="rotate-key">Rotate ingestion key</button>':''}</div><div class="settings-row"><label>Allowed browser origins</label><textarea id="settings-origins" aria-label="Allowed browser origins" rows="3" ${editor?'':'disabled'}>${esc((state.project.origins||[]).join("\n"))}</textarea><p>One exact origin per line. Leave empty for server-side ingestion only.</p>${editor?'<button class="button primary" id="save-settings">Save changes</button>':''}<p id="settings-error" class="error" role="alert"></p></div><div class="settings-row"><label>Export your data</label><p>Download events for the current date range as JSON.</p><button class="button" id="export-events">↓ Export events</button></div>${owner?`<div class="settings-row"><label>Data retention</label><p>Automatically limit how long event data is kept. Current policy: ${state.project.retention_days||365} days.</p><div class="inline-form"><input id="retention-days" type="number" min="1" max="3650" value="${state.project.retention_days||365}" aria-label="Retention days"><button class="button" id="save-retention">Save policy</button><button class="button" id="purge-expired">Purge expired now</button></div></div><div class="settings-row"><label>Privacy request</label><p>Permanently delete every event for one person in this project.</p><div class="inline-form"><input id="delete-person-id" placeholder="distinct_id" aria-label="Person distinct ID"><button class="button danger" id="delete-person">Delete person data</button></div></div><div class="settings-row danger-zone"><label>Danger zone</label><p>Deleting a project permanently removes its events, reports, dashboards, and configuration.</p><button class="button danger" id="delete-project">Delete this project</button></div>`:''}</div></section>`}
async function personDetail(id){$('#detail-content').innerHTML='<div class="loading">Loading activity…</div>';$('#detail-dialog').showModal();try{const q=params();q.set('person',id);q.set('page_size','100');const d=await api('/api/events?'+q);$('#detail-content').innerHTML=`<h2>${esc(id)}</h2><p>${fmt(d.total)} events in the selected period${d.total>100?' · latest 100 shown':''}</p><div>${d.events.map(e=>`<div class="timeline-item"><span><span class="event-symbol">ϟ</span>${esc(pretty(e.event))} <span class="tag">${esc(e.properties.$pathname||'—')}</span></span><time>${esc(new Date(e.timestamp).toLocaleString())}</time></div>`).join('')||'<p>No events found.</p>'}</div>`}catch(e){$('#detail-content').innerHTML=`<p class="error">${esc(e.message)}</p>`}}
function eventDetail(index){const e=state.events[index];if(!e)return;$('#detail-content').innerHTML=`<h2>${esc(pretty(e.event))}</h2><p>${esc(new Date(e.timestamp).toLocaleString())}</p><p>Person: <button class="person-link" data-detail-person="${esc(e.distinct_id)}">${esc(e.distinct_id)}</button></p><p>Session: ${esc(e.session_id||'Not supplied')}</p><label>Properties</label><pre class="properties">${esc(JSON.stringify(e.properties,null,2))}</pre><p class="small">Event ID: ${esc(e.id)}</p>`;$('#detail-dialog').showModal()}
function showPeopleList(title,people){$('#detail-content').innerHTML=`<h2>${esc(title)}</h2><p>${fmt(people.length)} ${people.length===1?'person':'people'} in this result.</p><div class="people-drilldown">${people.map(id=>`<button class="person-link drilldown-person" data-detail-person="${esc(id)}"><span class="event-symbol">♧</span>${esc(id)}</button>`).join('')||'<p>No people matched this result.</p>'}</div>`;$('#detail-dialog').showModal()}
function bindView(){let debounce;const search=$('#event-search');if(search)search.addEventListener('input',e=>{state.eventSearch=e.target.value;state.eventPage=1;clearTimeout(debounce);debounce=setTimeout(async()=>{const pos=search.selectionStart;await route();$('#event-search')?.focus();$('#event-search')?.setSelectionRange(pos,pos)},350)});const ps=$('#people-search');if(ps)ps.addEventListener('input',e=>{state.peopleSearch=e.target.value;clearTimeout(debounce);debounce=setTimeout(async()=>{const pos=ps.selectionStart;await route();$('#people-search')?.focus();$('#people-search')?.setSelectionRange(pos,pos)},350)});$('#event-filter')?.addEventListener('change',e=>{state.eventName=e.target.value;state.eventPage=1;route()});document.querySelectorAll('.funnel-select').forEach(el=>el.addEventListener('change',e=>{state.steps[+e.target.dataset.step]=e.target.value;route()}));$('#add-step')?.addEventListener('click',()=>{state.steps.push(state.steps.at(-1));route()});$('#remove-step')?.addEventListener('click',()=>{state.steps.pop();route()})}
window.addEventListener('hashchange',()=>{state.eventSearch='';state.eventName=state.pendingEventName||'';state.eventPage=1;state.pendingEventName=null;route()});
$('#date-range').addEventListener('change',e=>{state.days=+e.target.value;state.eventPage=1;route()});
let segmentTimer;
function updateSegment(){state.segmentProperty=$('#segment-property').value.trim();state.segmentValue=$('#segment-value').value.trim();state.eventPage=1;clearTimeout(segmentTimer);segmentTimer=setTimeout(route,450)}
$('#segment-property').addEventListener('input',updateSegment);
$('#segment-value').addEventListener('input',updateSegment);
$('#clear-segment').addEventListener('click',()=>{state.segmentProperty='';state.segmentValue='';state.eventPage=1;route()});
$('#theme-toggle').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';try{localStorage.setItem('pulse-theme',state.theme)}catch{}applyTheme()});
$('#save-view').addEventListener('click',async()=>{try{await saveCurrent()}catch(err){toast(err.message)}});
$('#language').addEventListener('change',e=>{state.lang=e.target.value==='id'?'id':'en';try{localStorage.setItem('pulse-language',state.lang)}catch{}applyLanguage();renderProjects();if(!$('#shell').hidden)route()});
$('#refresh').addEventListener('click',async()=>{await route();toast('Your view is up to date.')});
$('#help').addEventListener('click',()=>location.hash='guide');
$('#welcome-start').addEventListener('click',()=>{if(state.authenticated){$('#project-dialog').showModal()}else{$('#welcome').hidden=true;$('#login').hidden=false;$('#token').focus()}});
$('#new-project').addEventListener('click',()=>$('#project-dialog').showModal());
$('#project-picker').addEventListener('click',()=>$('#project-menu').hidden=!$('#project-menu').hidden);
$('#account').addEventListener('click',async()=>{await fetch('/api/logout',{method:'POST'});$('#shell').hidden=true;$('#login').hidden=false;$('#token').value=''});
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;$('#login-error').textContent='';try{await api('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:$('#token').value.trim()})});await boot()}catch(err){$('#login-error').textContent=err.message}finally{b.disabled=false}});
$('#project-form').addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;$('#project-error').textContent='';try{const p=await api('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('#new-name').value,origins:$('#new-origins').value.split(/[\n,]/).map(s=>s.trim()).filter(Boolean)})});state.projects.push(p);state.project=p;try{localStorage.setItem('pulse-project',p.id)}catch{};state.steps=[];$('#welcome').hidden=true;$('#login').hidden=true;$('#shell').hidden=false;renderProjects();$('#project-dialog').close();e.target.reset();location.hash='setup';await route();toast('Project created. Let’s connect your product.')}catch(err){$('#project-error').textContent=err.message}finally{b.disabled=false}});
document.addEventListener('click',async e=>{const target=e.target.closest('button,a,tr');if(!target)return;if(target.matches('.close-dialog')){target.closest('dialog').close();return}if(target.hasAttribute('data-project')){state.project=state.projects.find(p=>p.id===target.dataset.project);try{localStorage.setItem('pulse-project',state.project.id)}catch{};state.steps=[];state.eventName='';state.eventSearch='';$('#project-menu').hidden=true;renderProjects();route();return}if(target.hasAttribute('data-add-project')||target.dataset.action==='new'){$('#project-menu').hidden=true;$('#project-dialog').showModal();return}if(target.dataset.filterEvent){state.pendingEventName=target.dataset.filterEvent;if(state.view==='events'){state.eventName=state.pendingEventName;state.pendingEventName=null;route()}else{location.hash='events'}return}if(target.dataset.action){location.hash=target.dataset.action;return}if(target.hasAttribute('data-retry')){route();return}if(target.hasAttribute('data-metric')){state.metric=target.dataset.metric;document.querySelectorAll('[data-metric]').forEach(el=>el.classList.toggle('active',el.dataset.metric===state.metric));$('#activity-chart').innerHTML=chart(overviewData.series,state.metric);$('#legend-metric').textContent=state.metric==='users'?'Unique users':'Total events';return}if(target.dataset.person){personDetail(target.dataset.person);return}if(target.dataset.detailPerson){$('#detail-dialog').close();personDetail(target.dataset.detailPerson);return}if(target.dataset.eventIndex!==undefined){eventDetail(+target.dataset.eventIndex);return}if(target.hasAttribute('data-copy')){try{await navigator.clipboard.writeText(target.parentElement.querySelector('code').textContent);target.textContent='Copied';setTimeout(()=>target.textContent='Copy',1600)}catch{toast('Select the code and copy it with your keyboard.')}return}if(target.id==='save-settings'){target.disabled=true;try{const p=await api('/api/projects',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:state.project.id,name:$('#settings-name').value,origins:$('#settings-origins').value.split(/[\n,]/).map(s=>s.trim()).filter(Boolean)})});state.project=p;state.projects=state.projects.map(old=>old.id===p.id?p:old);renderProjects();toast('Project settings saved.')}catch(err){$('#settings-error').textContent=err.message}finally{target.disabled=false}return}if(target.id==='export-events'){const a=document.createElement('a');a.href=query('/api/export');a.download='pulse-events.json';a.click()}});
document.addEventListener('click',async e=>{const target=e.target.closest('button');if(!target)return;if(target.dataset.funnelIndex!==undefined){const step=state.funnel[+target.dataset.funnelIndex];showPeopleList(`${pretty(step.name)} — completed`,step.people||[])}if(target.dataset.funnelDropoff!==undefined){const step=state.funnel[+target.dataset.funnelDropoff];showPeopleList(`Dropped before ${pretty(step.name)}`,step.dropoff_people||[])}if(target.dataset.openSaved){const item=state.reports.find(saved=>saved.id===target.dataset.openSaved);if(!item)return;const c=item.config||{},views=new Set(['overview','events','funnels','retention','paths','people']);state.days=Number.isInteger(c.days)&&c.days>=1&&c.days<=366?c.days:30;state.metric=c.metric==='events'?'events':'users';state.eventName=typeof c.eventName==='string'?c.eventName:'';state.steps=Array.isArray(c.steps)?c.steps.filter(step=>typeof step==='string').slice(0,8):[];state.segmentProperty=typeof c.property==='string'?c.property:'';state.segmentValue=typeof c.value==='string'?c.value:'';$('#date-range').value=String(state.days);const view=views.has(c.view)?c.view:item.report_type;location.hash=views.has(view)?view:'overview'}if(target.dataset.deleteSaved){await api(`/api/reports?project=${encodeURIComponent(state.project.id)}&id=${encodeURIComponent(target.dataset.deleteSaved)}`,{method:'DELETE'});toast('Saved analysis deleted.');route()}});

document.addEventListener('click',e=>{const target=e.target.closest('[data-event-page]');if(!target||target.disabled)return;state.eventPage=Number(target.dataset.eventPage);route();document.querySelector('main')?.scrollTo?.({top:0,behavior:'smooth'})});

document.addEventListener('submit',async e=>{const form=e.target;if(!['token-form','dashboard-form','annotation-form','alert-form'].includes(form.id))return;e.preventDefault();const button=form.querySelector('button');button.disabled=true;const data=new FormData(form),project=encodeURIComponent(state.project.id);try{if(form.id==='token-form'){const result=await api('/api/access-tokens',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:data.get('name'),role:data.get('role')})});$('#detail-content').innerHTML=`<h2>Access token created</h2><p>Copy this token now. For security, Pulse will not show it again.</p>${snippet(result.token)}<p class="small">Role: ${esc(result.access.role)} · ${esc(result.access.name)}</p>`;$('#detail-dialog').showModal()}if(form.id==='dashboard-form'){await api(`/api/dashboards?project=${project}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:data.get('name'),report_ids:data.getAll('report_ids')})});toast('Dashboard shared.')}if(form.id==='annotation-form'){await api(`/api/annotations?project=${project}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:data.get('title'),description:data.get('description'),occurred_at:new Date(data.get('occurred_at')).toISOString()})});toast('Annotation added.')}if(form.id==='alert-form'){await api(`/api/alerts?project=${project}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:data.get('name'),metric:data.get('metric'),comparison:data.get('comparison'),threshold:Number(data.get('threshold')),enabled:true})});toast('Alert rule added.')}await route()}catch(err){toast(err.message)}finally{button.disabled=false}});

document.addEventListener('click',async e=>{const target=e.target.closest('button');if(!target)return;const project=encodeURIComponent(state.project?.id||'');try{if(target.dataset.revokeToken){if(!confirm('Revoke this access token?'))return;await api(`/api/access-tokens?id=${encodeURIComponent(target.dataset.revokeToken)}`,{method:'DELETE'});toast('Access revoked.');return route()}if(target.dataset.deleteDashboard){await api(`/api/dashboards?project=${project}&id=${encodeURIComponent(target.dataset.deleteDashboard)}`,{method:'DELETE'});return route()}if(target.dataset.deleteAnnotation){await api(`/api/annotations?project=${project}&id=${encodeURIComponent(target.dataset.deleteAnnotation)}`,{method:'DELETE'});return route()}if(target.dataset.deleteAlert){await api(`/api/alerts?project=${project}&id=${encodeURIComponent(target.dataset.deleteAlert)}`,{method:'DELETE'});return route()}if(target.id==='rotate-key'){if(!confirm('Rotate the ingestion key? Existing SDK installations will stop sending data until updated.'))return;const p=await api(`/api/project-policy?project=${project}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'rotate_key'})});replaceProject(p);toast('Ingestion key rotated.');return route()}if(target.id==='save-retention'){const p=await api(`/api/project-policy?project=${project}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({retention_days:Number($('#retention-days').value)})});replaceProject(p);toast('Retention policy saved.');return route()}if(target.id==='purge-expired'){if(!confirm('Permanently delete all events older than the retention policy?'))return;const result=await api(`/api/project-policy?project=${project}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'purge_expired'})});toast(`${fmt(result.deleted)} expired events deleted.`)}if(target.id==='delete-person'){const id=$('#delete-person-id').value.trim();if(!id||!confirm(`Permanently delete all event data for ${id}?`))return;const result=await api(`/api/project-policy?project=${project}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'delete_person',distinct_id:id})});toast(`${fmt(result.deleted)} events deleted.`);$('#delete-person-id').value=''}if(target.id==='delete-project'){if(prompt(`Type ${state.project.name} to permanently delete this project.`)!==state.project.name)return;await api(`/api/project-policy?project=${project}`,{method:'DELETE'});state.projects=state.projects.filter(p=>p.id!==state.project.id);state.project=state.projects[0]||null;renderProjects();location.hash='overview';toast('Project deleted.');return route()}}catch(err){toast(err.message)}});

function replaceProject(project){state.project=project;state.projects=state.projects.map(item=>item.id===project.id?project:item);renderProjects()}
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-event-index]'))eventDetail(+e.target.dataset.eventIndex)});
document.addEventListener('click',e=>{if(!e.target.closest('#project-picker')&&!e.target.closest('#project-menu'))$('#project-menu').hidden=true});
setInterval(()=>{if(state.view==='events'&&!document.hidden&&!$('#shell').hidden&&!$('#detail-dialog').open&&document.activeElement?.id!=='event-search')route()},15000);
applyTheme();
applyLanguage();
boot();
